<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { getInterviewOptions } from '@/services/interviewService'
import { createInterviewSlot,getCalendarEvents } from '@/services/calendarService'
import { disconnectGoogle, getGoogleAuthorization, getGoogleStatus } from '@/services/integrationService'
const auth=useAuthStore(),events=ref([]),options=ref({applications:[],interviewers:[]}),error=ref(''),message=ref(''),loading=ref(false)
const google=ref({enabled:false,connected:false})
async function connectGoogle(){try{const result=await getGoogleAuthorization();window.location.assign(result.authorizationUrl)}catch(e){error.value=e.response?.data?.message||'無法連結 Google Calendar'}}
async function disconnectCalendar(){if(!window.confirm('確定解除 Google Calendar 連結？'))return;try{await disconnectGoogle();google.value=await getGoogleStatus();message.value='已解除 Google Calendar'}catch(e){error.value=e.response?.data?.message||'無法解除連結'}}
const now=new Date(),range=reactive({from:new Date(now.getFullYear(),now.getMonth(),1).toISOString(),to:new Date(now.getFullYear(),now.getMonth()+1,1).toISOString()})
const form=reactive({applicationId:'',roundNumber:1,startsAt:'',endsAt:'',format:'ONLINE',location:'',interviewerIds:[]})
const canPropose=computed(()=>auth.hasAnyRole(['HR']))
async function load(){loading.value=true;error.value='';try{[events.value,google.value]=await Promise.all([getCalendarEvents(range.from,range.to),getGoogleStatus()]);if(canPropose.value)options.value=await getInterviewOptions()}catch(e){error.value=e.response?.data?.message||'無法取得行事曆'}finally{loading.value=false}}
async function propose(){try{await createInterviewSlot({...form,applicationId:Number(form.applicationId),roundNumber:Number(form.roundNumber),startsAt:new Date(form.startsAt).toISOString(),endsAt:new Date(form.endsAt).toISOString(),interviewerIds:form.interviewerIds.map(Number)});message.value='候選面試時段已寄出通知';await load()}catch(e){error.value=e.response?.data?.message||'建立時段失敗'}}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">COMPANY CALENDAR</p><h1>公司面試行事曆</h1><p>HR 可跨部門管理；主管只看自己部門；面試官只看指派給自己的行程。</p></div></div>
<p v-if="error" class="alert-message is-error">{{error}}</p><p v-if="message" class="alert-message is-success">{{message}}</p>
<article class="detail-card calendar-connection"><div><p class="eyebrow">PERSONAL CALENDAR</p><h2>Google Calendar</h2><p>{{google.enabled?(google.connected?'已連結，參與的面試會同步到個人行事曆。':'連結後可將參與的面試同步到個人行事曆。'):'尚未啟用 Google Calendar，請先設定後端 OAuth。'}}</p></div><button v-if="google.enabled" :class="google.connected?'secondary-button':'primary-button page-action'" type="button" @click="google.connected?disconnectCalendar():connectGoogle()">{{google.connected?'解除連結':'連結 Google Calendar'}}</button></article>
<form v-if="canPropose" class="form-card calendar-slot-form" @submit.prevent="propose"><div class="card-heading"><div><p class="eyebrow">INTERVIEW AVAILABILITY</p><h2>提供求職者可選時段</h2><p>填寫時段並指派面試官，求職者將在應徵頁面確認。</p></div></div><div class="form-grid"><label>應徵紀錄<select v-model="form.applicationId" required><option value="">請選擇</option><option v-for="a in options.applications" :key="a.id" :value="a.id">{{a.candidateName}}｜{{a.jobTitle}}</option></select></label><label>輪次<input v-model="form.roundNumber" type="number" min="1" required></label><label>開始<input v-model="form.startsAt" type="datetime-local" required></label><label>結束<input v-model="form.endsAt" type="datetime-local" required></label><label>形式<select v-model="form.format"><option value="ONLINE">線上</option><option value="ONSITE">實體</option><option value="PHONE">電話</option></select></label><label>地點／連結<input v-model.trim="form.location"></label><fieldset class="span-full interviewer-picker"><legend>面試官</legend><div class="interviewer-options"><label v-for="u in options.interviewers" :key="u.id"><input v-model="form.interviewerIds" type="checkbox" :value="u.id"><span><strong>{{u.displayName}}</strong><small>{{u.departmentName}}</small></span></label></div><p v-if="!options.interviewers.length">目前沒有可指派的面試官</p></fieldset></div><div class="calendar-form-footer"><button class="primary-button page-action" :disabled="!form.interviewerIds.length">新增候選時段</button></div></form>
<article class="data-card calendar-list"><div v-if="loading" class="table-state">載入中…</div><div v-else-if="!events.length" class="table-state">本月沒有面試行程</div><div v-else v-for="event in events" :key="event.id" class="calendar-row"><time>{{new Date(event.startsAt).toLocaleString('zh-TW')}}</time><div><strong>{{event.candidateName}}｜{{event.jobTitle}}</strong><p>{{event.departmentName}} · {{event.eventType==='PROPOSED'?'候選時段':'已確認'}} · {{event.location||'地點待確認'}}</p></div></div></article></section></template>
